import React, { useEffect, useState } from "react";
import io from "socket.io-client";

const socket = io("http://localhost:5000");

export default function Socket({ currentUser }) {
  const [allUsers, setAllUsers] = useState([]);
  const [searchUser, setSearchUser] = useState("");
  const [selectedUser, setSelectedUser] = useState(null);
  const [chatMessages, setChatMessages] = useState([]);
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (!currentUser) return;

    socket.emit("set username", currentUser);

    socket.on("active users", (users) => setAllUsers(users));
    socket.on("load messages", (msgs) => setChatMessages(msgs));
    socket.on("private message", (msg) => setChatMessages((prev) => [...prev, msg]));
    socket.on("delete message locally", (id) =>
      setChatMessages((prev) => prev.filter((m) => m._id !== id))
    );
    socket.on("delete message globally", (id) =>
      setChatMessages((prev) => prev.filter((m) => m._id !== id))
    );

    return () => {
      socket.off("active users");
      socket.off("load messages");
      socket.off("private message");
      socket.off("delete message locally");
      socket.off("delete message globally");
    };
  }, [currentUser]);

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!message.trim() || !selectedUser) return;

    socket.emit("private message", {
      to: selectedUser,
      content: message,
    });

    setMessage("");
  };

  const filteredUsers = allUsers.filter(
    (u) => u !== currentUser && u.toLowerCase().includes(searchUser.toLowerCase())
  );

  const filteredMessages = chatMessages.filter(
    (m) =>
      (m.from === currentUser && m.to === selectedUser) ||
      (m.from === selectedUser && m.to === currentUser)
  );

  return (
    <div style={styles.container}>
      <h3>💬 Chat</h3>
      <input
        placeholder="Search user..."
        value={searchUser}
        onChange={(e) => setSearchUser(e.target.value)}
        style={styles.searchInput}
      />
      <div style={styles.userList}>
        {filteredUsers.map((user) => (
          <div
            key={user}
            style={{
              ...styles.userItem,
              backgroundColor: user === selectedUser ? "#d0eaff" : "white",
            }}
            onClick={() => setSelectedUser(user)}
          >
            {user}
          </div>
        ))}
      </div>

      {selectedUser && (
        <>
          <div style={styles.chatBox}>
            {filteredMessages.map((msg) => (
              <div
                key={msg._id}
                style={{
                  ...styles.message,
                  alignSelf: msg.from === currentUser ? "flex-end" : "flex-start",
                  backgroundColor: msg.from === currentUser ? "#4a90e2" : "#eee",
                  color: msg.from === currentUser ? "white" : "black",
                }}
              >
                {msg.content}
              </div>
            ))}
          </div>
          <form onSubmit={handleSendMessage} style={styles.form}>
            <input
              type="text"
              placeholder="Type a message..."
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              style={styles.messageInput}
            />
            <button type="submit" style={styles.sendButton}>
              Send
            </button>
          </form>
        </>
      )}
    </div>
  );
}

const styles = {
  container: {
    border: "1px solid #ccc",
    borderRadius: 6,
    width: 320,
    padding: 10,
    backgroundColor: "white",
  },
  searchInput: {
    width: "100%",
    padding: 8,
    marginBottom: 8,
    borderRadius: 4,
    border: "1px solid #ccc",
  },
  userList: {
    maxHeight: 100,
    overflowY: "auto",
    border: "1px solid #ccc",
    marginBottom: 10,
  },
  userItem: {
    padding: 8,
    borderBottom: "1px solid #eee",
    cursor: "pointer",
  },
  chatBox: {
    height: 220,
    overflowY: "auto",
    border: "1px solid #ccc",
    padding: 10,
    display: "flex",
    flexDirection: "column",
    gap: 6,
    marginBottom: 10,
  },
  message: {
    maxWidth: "70%",
    padding: 10,
    borderRadius: 10,
    wordBreak: "break-word",
  },
  form: {
    display: "flex",
    gap: 8,
  },
  messageInput: {
    flexGrow: 1,
    padding: 8,
    borderRadius: 4,
    border: "1px solid #ccc",
  },
  sendButton: {
    backgroundColor: "#4a90e2",
    color: "white",
    border: "none",
    padding: "8px 12px",
    borderRadius: 4,
    cursor: "pointer",
  },
};
